		validator.validate( command );

            entity.setDispositionReviewId( command.getDispositionReviewId() );
            entity.setReviewDate( command.getReviewDate() );
            entity.setReviewer( command.getReviewer() );
            entity.setNotes( command.getNotes() );
            entity.setOutcome( command.getOutcome() );

